import { createRequire } from 'module'
const require = createRequire('D:/repository/苏住房G/package.json')
const LIB = 'D:/repository/苏住房G/e2e/std-evaluation/lib/std-eval-lib.cjs'
const { createSuite } = require(LIB)

const suite = createSuite({ name: 'shot-6582', task: 'verify', dir: 'shot-6582' })

suite.run(async ({ page, ui, step, note }) => {
  const p = await page()
  await ui.login(p)
  const base = (process.env.E2E_BASE_URL || 'http://127.0.0.1:8101').replace(/\/$/, '')
  await step('home', async () => {
    await p.goto(`${base}/#/index`, { waitUntil: 'domcontentloaded' })
    await p.waitForTimeout(8000)
    console.log('URL:', p.url())
    // 定位关键数据导航卡片区域截图
    const el = await p.$('text=关键数据导航')
    const card = el ? await el.evaluateHandle(n => n.closest('.el-card') || n.parentElement) : null
    const box = card ? await card.boundingBox() : null
    if (box) {
      await p.screenshot({ path: `${base.replace(/[^a-z0-9]/gi,'')}.png` }).catch(()=>{})
      await p.screenshot({ path: 'e2e/artifacts/fix-6582/keydatanav.png', clip: { x: box.x, y: box.y, width: Math.min(box.width, 900), height: 260 } }).catch(e=>console.log('clip fail', e.message))
    }
    await p.screenshot({ path: 'e2e/artifacts/fix-6582/home-full.png', fullPage: true }).catch(e=>console.log('full fail', e.message))
    console.log('box:', JSON.stringify(box))
  })
  note('done')
})

